tool_input.command:
cd "$(pwd)" && node -e "
const fs=require('fs');let s=fs.readFileSync('src/data/products.ts','utf8');
const facts={'canvas-field-tote':'18 oz canvas','waxed-day-pack':'22 litre','weekender-duffel':'45 litre','merino-crew-sweater':'Merino wool','heavyweight-pocket-tee':'240 gsm jersey','cotton-chore-coat':'Cotton twill','enamel-camp-mug':'350 ml','cast-iron-skillet':'Pre-seasoned','linen-tea-towels':'Set of two','leather-key-ring':'Brass ring','ribbed-wool-beanie':'Wool blend'};
for(const [k,v] of Object.entries(facts)){s=s.replace(new RegExp(\"(slug: '\"+k+\"',[\\\\s\\\\S]*?tone: '\\\\w+',)\"),'\$1\n    specFact: \''+v+'\',');}
s=s.replace('  /** Picks the colour of the image placeholder box. */\n  tone: Tone;','  /** Picks the colour of the image placeholder box. */\n  tone: Tone;\n  /** One short fact for the spec plate caption, e.g. \"18 oz canvas\". */\n  specFact: string;');
fs.writeFileSync('src/data/products.ts',s);" && grep -c specFact src/data/products.ts
